(()=>{'use strict';document.querySelectorAll('[data-launch-form]').forEach(form=>{let tokenPromise;const status=form.querySelector('[data-launch-status]');const vacancy=new URLSearchParams(location.search).get('vacancy');if(form.elements.vacancy&&Array.from(form.elements.vacancy.options).some(o=>o.value===vacancy))form.elements.vacancy.value=vacancy;const getToken=()=>tokenPromise||(tokenPromise=fetch('https://files.nsats.com/mynsats/csrf',{credentials:'include',cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Please try again.');return r.json()}).then(x=>{form.elements.csrf.value=x.csrf}));form.addEventListener('submit',async e=>{if(form.dataset.ready==='yes')return;e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await getToken();const file=form.elements.resume?.files[0];if(file&&file.size>10*1024*1024)throw Error('Choose a résumé no larger than 10 MB.');form.dataset.ready='yes';button.disabled=false;form.requestSubmit(button)}catch(err){tokenPromise=null;if(status)status.textContent='We could not submit this form. '+err.message}finally{button.disabled=false}})});})();